      "      {",
      "        \"name\": \"Ask Open Everywhere\",",
      "        \"type\": \"global\",",
      "        \"callback_id\": \"oe_global_shortcut\",",
      "        \"description\": \"Wake the agent in a DM.\"",
      "      }",
      "    ]",
      "  },",
      "  \"oauth_config\": {",
      "    \"redirect_urls\": [",
      "      \"https://YOUR-DEPLOY-URL/setup/callback\"",
